esqlQuery.esql:
FROM metrics-netgear_genie.status-*
// The status data stream writes one document for every poll, whether or not
// the modem answered, so a window that holds polls but no healthy one means
// the web interface is unusable rather than merely unmonitored. Requiring
// every poll in the window to be unhealthy keeps a single slow or dropped
// poll from raising an alert.
| STATS polls = COUNT(*),
        healthy = COUNT(CASE(netgear_genie.status.web_ui.state == "ok", 1, null)),
        states = VALUES(netgear_genie.status.web_ui.state),
        reasons = VALUES(netgear_genie.status.web_ui.reason)
| WHERE healthy == 0
